<?php
declare(strict_types=1);

namespace Scutoons\Infrastructure\Config;

/**
 * All settings of the server. Lookup order per key: environment variable `QR_<KEY>` → for the media storage keys only
 * (DOTENV_KEYS: the bunny.net credentials + CDN_PUBLIC_URL) the plain environment variable `<KEY>`, then the same key in
 * the repository-root `.env` → PHP constant `<KEY>` (`config.local.php` locally, `config.php` generated by the deploy
 * workflow in production) → the default in `config/settings.php`. An empty value falls back to the next source.
 * The root `.env` is the owner's deploy checklist with PRODUCTION values (FTP, DB, AUTH_SECRET, SMTP …): only the
 * whitelisted keys are ever read from it – a dev server must never pick up the production database or secrets.
 * Secrets never go into the repository and are never printed. Every key is documented in docs/CONFIGURATION.md.
 */
final class Settings
{
    /** The only keys read from the repository-root .env (and from plain, non-QR_ environment variables) */
    public const DOTENV_KEYS = ['BUNNY_STORAGE_ZONE', 'BUNNY_STORAGE_ENDPOINT', 'BUNNY_STORAGE_PASSWORD', 'BUNNY_STORAGE_READONLY_PASSWORD', 'BUNNY_PULLZONE_ID', 'BUNNY_API_KEY', 'CDN_PUBLIC_URL'];

    /**
     * @param array<string, string> $defaults
     * @param bool $isolated only $defaults count (no environment, no constants) – unit tests
     * @param array<string, string> $dotenv the whitelisted values of the root .env (readDotEnv)
     */
    public function __construct(private readonly string $root, private readonly array $defaults, private readonly bool $isolated = false, private readonly array $dotenv = [])
    {
    }

    /**
     * Settings from the defaults plus $values only – for unit tests (ignores QR_* variables and constants)
     * @param array<string, string> $values
     */
    public static function fixed(string $root, array $values): self
    {
        $root = rtrim(str_replace('\\', '/', $root), '/');
        /** @var array<string, string> $defaults */
        $defaults = require "$root/config/settings.php";
        return new self($root, $values + $defaults, true);
    }

    /**
     * Loads the constants file of this installation (config.local.php, else config.php), the whitelisted keys of the
     * repository-root .env (../.env from the server folder; absent in production) and the defaults.
     * Safe to call more than once (the constants file is required once).
     */
    public static function load(?string $root = null, ?string $dotenvFile = null): self
    {
        $root = rtrim(str_replace('\\', '/', $root ?? dirname(__DIR__, 3)), '/');
        foreach (['config.local.php', 'config.php'] as $file) {
            if (is_file("$root/$file")) {
                require_once "$root/$file";
                break;
            }
        }
        /** @var array<string, string> $defaults */
        $defaults = require "$root/config/settings.php";
        return new self($root, $defaults, false, self::readDotEnv($dotenvFile ?? dirname($root) . '/.env'));
    }

    /**
     * The whitelisted keys (DOTENV_KEYS) of a .env file; every other line is ignored. Missing / unreadable file = [].
     * @return array<string, string>
     */
    public static function readDotEnv(string $file): array
    {
        if (!is_file($file) || !is_readable($file)) return [];
        return array_intersect_key(self::parseDotEnv((string) file_get_contents($file)), array_flip(self::DOTENV_KEYS));
    }

    /**
     * Parses .env text: `KEY=value` lines, `#` comments, optional `export `, values in single or double quotes, an
     * unquoted value ends at ` #`. No interpolation, no escapes. Returns the pairs; never echoes them.
     * @return array<string, string>
     */
    public static function parseDotEnv(string $text): array
    {
        $values = [];
        foreach (preg_split('/\r?\n/', $text) ?: [] as $line) {
            $line = trim($line);
            if ($line === '' || $line[0] === '#') continue;
            if (str_starts_with($line, 'export ')) $line = ltrim(substr($line, 7));
            if (!preg_match('/^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/', $line, $m)) continue;
            $value = $m[2];
            if ($value !== '' && ($value[0] === '"' || $value[0] === "'")) {
                $end = strpos($value, $value[0], 1);
                $value = $end === false ? substr($value, 1) : substr($value, 1, $end - 1);
            } else {
                $value = trim((string) preg_replace('/(^|\s+)#.*$/', '', $value));
            }
            $values[$m[1]] = $value;
        }
        return $values;
    }

    /** The server folder (the one with composer.json) */
    public function root(): string
    {
        return $this->root;
    }

    public function get(string $key): string
    {
        if ($this->isolated) return $this->defaults[$key] ?? '';
        $env = getenv('QR_' . $key);
        if ($env !== false && $env !== '') return $env;
        if (in_array($key, self::DOTENV_KEYS, true)) {
            $plain = getenv($key); // the real environment wins over the .env file
            if ($plain !== false && $plain !== '') return $plain;
            if (($this->dotenv[$key] ?? '') !== '') return $this->dotenv[$key];
        }
        if (defined($key)) {
            $constant = constant($key);
            if (is_scalar($constant) && (string) $constant !== '') return (string) $constant;
        }
        return $this->defaults[$key] ?? '';
    }

    public function int(string $key): int
    {
        return (int) $this->get($key);
    }

    public function bool(string $key): bool
    {
        return in_array(strtolower($this->get($key)), ['1', 'true', 'yes', 'on'], true);
    }

    /** @return list<string> comma separated values */
    public function list(string $key): array
    {
        return array_values(array_filter(array_map('trim', explode(',', $this->get($key))), fn(string $v) => $v !== ''));
    }

    /**
     * Browser origins that may call the API: ALLOWED_ORIGINS, plus on a local dev server (`php -S`, which production
     * never runs) http://localhost:<port> and http://127.0.0.1:<port> for every port in shared/dev-ports.json (the
     * single source of the local dev ports), so a new local app needs no config.local.php entry.
     * @return list<string>
     */
    public function allowedOrigins(): array
    {
        $origins = $this->list('ALLOWED_ORIGINS');
        if (!$this->isolated && PHP_SAPI === 'cli-server') {
            $origins = [...$origins, ...self::devOrigins(dirname($this->root) . '/shared/dev-ports.json')];
        }
        return array_values(array_unique($origins));
    }

    /**
     * The local origins of every port in a dev ports file (shared/dev-ports.json); none when it is missing
     * (production has no shared/ folder).
     * @return list<string>
     */
    public static function devOrigins(string $portsFile): array
    {
        $ports = is_file($portsFile) ? json_decode((string) file_get_contents($portsFile), true) : null;
        if (!is_array($ports)) return [];
        $origins = [];
        foreach ($ports as $port) {
            if (!is_int($port)) continue; // "$comment"
            $origins[] = "http://localhost:$port";
            $origins[] = "http://127.0.0.1:$port";
        }
        return $origins;
    }

    /** A path setting; relative values are relative to the server folder */
    public function path(string $key): string
    {
        $value = str_replace('\\', '/', $this->get($key));
        if ($value === '') return '';
        $absolute = str_starts_with($value, '/') || preg_match('#^[A-Za-z]:/#', $value) === 1;
        return $absolute ? $value : $this->root . '/' . $value;
    }
}
